package com.gamehub.application.controller; import com.gamehub.application.service.TournamentRegistrationService; import java.util.List; public final class RegistrationController {private final TournamentRegistrationService service;public RegistrationController(TournamentRegistrationService s){service=s;}public List<String> tournaments()throws Exception{return service.tournaments();}public List<String> registrations(long t)throws Exception{return service.registrations(t);}public List<String> teams(long c)throws Exception{return service.teams(c);}public long registerSolo(long t,long c)throws Exception{return service.solo(t,c);}public long registerTeam(long t,long c,long team)throws Exception{return service.team(t,c,team);}}